"use client";

import { animate, motion, useMotionValue, useReducedMotion, type Transition } from "motion/react";
import { type ComponentPropsWithoutRef, type ReactNode, useEffect, useRef, useState } from "react";

import { cn } from "@/lib/utils";

/** Props for an undo button. Pass `pending` to control the undo window, or `defaultPending` to let the button hold it. */
export type UndoButtonProps = Omit<ComponentPropsWithoutRef<"button">, "children"> & {
  /** The action, such as "Archive". */
  children: ReactNode;
  /** Runs at once on the first press. Do the work here, in a way `onUndo` can reverse. */
  onAction: () => void;
  /** Runs when the person presses Undo before the time runs out. */
  onUndo: () => void;
  /** Runs when the time runs out and the action is final. */
  onCommit?: () => void;
  /** Whether the undo window is open. */
  pending?: boolean;
  defaultPending?: boolean;
  onPendingChange?: (pending: boolean) => void;
  undoLabel?: string;
  /** How long Undo stays, in milliseconds. Time spent paused does not count. */
  duration?: number;
  /** Read out when the action runs. The visible label only says "Undo". */
  doneMessage?: string;
  undoneMessage?: string;
};

const SWAP: Transition = { duration: 0.2, ease: [0.165, 0.84, 0.44, 1] };
// A fade is not motion, so reduced motion keeps it and drops the blur.
const FADE: Transition = { duration: 0.15 };

/**
 * Runs an action at once, then turns into Undo while a ring drains. When the
 * ring is empty the action is final. Coming back to the button with the
 * pointer or the keyboard pauses the countdown.
 */
export function UndoButton({
  children,
  onAction,
  onUndo,
  onCommit,
  pending,
  defaultPending = false,
  onPendingChange,
  undoLabel = "Undo",
  duration = 5000,
  doneMessage = "Done. You can undo this for a few seconds.",
  undoneMessage = "Undone",
  className,
  onClick,
  onPointerEnter,
  onPointerLeave,
  onFocus,
  onBlur,
  ...buttonProps
}: UndoButtonProps) {
  const [ownPending, setOwnPending] = useState(defaultPending);
  const open = pending ?? ownPending;
  // The hover and the focus that pressed the action do not count: only coming back pauses.
  const [hovered, setHovered] = useState(false);
  const [focused, setFocused] = useState(false);
  const [message, setMessage] = useState("");
  const paused = open && (hovered || focused);
  // The share of the ring still drawn, from 1 to 0.
  const ring = useMotionValue(1);
  const remaining = useRef(duration);
  const reduceMotion = useReducedMotion();
  const handlers = useRef({ onCommit, onPendingChange });
  useEffect(() => {
    handlers.current = { onCommit, onPendingChange };
  }, [onCommit, onPendingChange]);

  const setOpen = (next: boolean) => {
    if (pending === undefined) setOwnPending(next);
    handlers.current.onPendingChange?.(next);
  };
  const setOpenRef = useRef(setOpen);
  useEffect(() => {
    setOpenRef.current = setOpen;
  });

  useEffect(() => {
    if (!open) {
      remaining.current = duration;
      ring.set(1);
      return;
    }
    if (paused) return;
    const startedAt = Date.now();
    ring.set(remaining.current / Math.max(1, duration));
    // Linear, because the ring stands for time: the person judges what is left from its length.
    const drain = animate(ring, 0, { duration: remaining.current / 1000, ease: "linear" });
    const timer = window.setTimeout(() => {
      setMessage("");
      handlers.current.onCommit?.();
      setOpenRef.current(false);
    }, remaining.current);
    return () => {
      window.clearTimeout(timer);
      drain.stop();
      remaining.current = Math.max(0, remaining.current - (Date.now() - startedAt));
    };
  }, [duration, open, paused, ring]);

  const press = () => {
    setHovered(false);
    setFocused(false);
    if (open) {
      onUndo();
      setMessage(undoneMessage);
      setOpen(false);
    } else {
      onAction();
      setMessage(doneMessage);
      setOpen(true);
    }
  };

  const hidden = { opacity: 0, filter: reduceMotion ? "blur(0px)" : "blur(4px)" };
  const shown = { opacity: 1, filter: "blur(0px)" };
  const swap = reduceMotion ? FADE : SWAP;

  return (
    <>
      <button
        {...buttonProps}
        type="button"
        data-pending={open}
        data-paused={paused}
        onClick={(event) => {
          onClick?.(event);
          if (!event.defaultPrevented) press();
        }}
        onPointerEnter={(event) => {
          onPointerEnter?.(event);
          if (event.pointerType === "mouse") setHovered(true);
        }}
        onPointerLeave={(event) => {
          onPointerLeave?.(event);
          setHovered(false);
        }}
        onFocus={(event) => {
          onFocus?.(event);
          setFocused(true);
        }}
        onBlur={(event) => {
          onBlur?.(event);
          setFocused(false);
        }}
        className={cn(
          "inline-flex min-h-11 cursor-pointer touch-manipulation items-center justify-center rounded-full border border-border bg-background px-4 text-sm font-medium text-foreground outline-none",
          "motion-safe:transition motion-safe:duration-150 hover:bg-muted active:scale-97",
          "focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background",
          "disabled:cursor-not-allowed disabled:opacity-50 disabled:active:scale-100",
          className,
        )}
      >
        {/* Both labels sit in one grid cell, so the button keeps the width of the wider one. */}
        <span className="grid">
          <motion.span
            aria-hidden={open}
            initial={false}
            animate={open ? hidden : shown}
            transition={swap}
            className="col-start-1 row-start-1 flex items-center justify-center gap-2 whitespace-nowrap"
          >
            {children}
          </motion.span>
          <motion.span
            aria-hidden={!open}
            initial={false}
            animate={open ? shown : hidden}
            transition={swap}
            className="col-start-1 row-start-1 flex items-center justify-center gap-2 whitespace-nowrap"
          >
            {/* Turned a quarter back, so the ring drains from the top. */}
            <svg viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.75" aria-hidden="true" className="size-4 shrink-0 -rotate-90">
              <circle cx="8" cy="8" r="6" className="opacity-25" />
              <motion.circle cx="8" cy="8" r="6" strokeLinecap="round" style={{ pathLength: ring }} />
            </svg>
            {undoLabel}
          </motion.span>
        </span>
      </button>
      {/* Outside the button, so the result is not also read as part of its name. */}
      <span className="sr-only" role="status">
        {message}
      </span>
    </>
  );
}
